package dbguild

// Este fichero es el espejo de `DBModuleLeveling` en
// `libraries/library-shared/src/db/schemas/DBGuildSchemas.ts`. Como con
// tickets, el módulo de niveles no tiene contrapartida en ningún zod schema
// de Node — nace directamente en api-db-go y en el dashboard —, así que el
// ORDEN de los campos sigue al del interfaz de TypeScript tal cual, no a un
// schema-definition ajeno.
//
// Los campos nullable (`string | null`, `number | null` en TS) usan punteros
// para que la codificación JSON emita `null` (nunca el cero del tipo) en la
// variante sin valor. Los campos de colección (`[]string`, `Record<...>`)
// NUNCA llevan `omitempty`: un valor presente-pero-vacío tiene que serializar
// como `[]` / `{}`, jamás `null`. `NormalizeLeveling` rellena las colecciones
// que decodifican `nil` para sostener ese invariante en los documentos leídos
// de Mongo/Redis.
//
// El histórico de XP en sí (mensajes, tiempo en voz, niveles por miembro) NO
// vive aquí: vive en Postgres (`leveling.user_stats`, ver
// `internal/infrastructure/postgres/leveling_repository.go`). Este
// subdocumento es SOLO la configuración por-guild.

// LevelingXPMode espeja `LevelingXpMode`: el almacenamiento SIEMPRE guarda XP
// de texto y de voz por separado (ver `ModuleLeveling.Text`/`.Voice`); este
// campo es una decisión de LECTURA, no de escritura — "unified" deriva nivel
// y rank de `text_xp + voice_xp`, "separate" lleva progresión propia de cada
// fuente. Cambiar el modo nunca destruye datos.
type LevelingXPMode string

const (
	LevelingXPModeUnified  LevelingXPMode = "unified"
	LevelingXPModeSeparate LevelingXPMode = "separate"
)

// LevelingCommandMode espeja `LevelingCommandMode` — mismo patrón que
// `TempvoiceCommandMode`: cómo se puede invocar el (único) comando del
// módulo, `rank`.
type LevelingCommandMode string

const (
	LevelingCommandModeSlash  LevelingCommandMode = "slash"
	LevelingCommandModePrefix LevelingCommandMode = "prefix"
	LevelingCommandModeBoth   LevelingCommandMode = "both"
)

// LevelingAnnounceTarget espeja `LevelingAnnounceTarget` — dónde se publica
// el anuncio de subida de nivel.
type LevelingAnnounceTarget string

const (
	LevelingAnnounceTargetCurrent LevelingAnnounceTarget = "current"
	LevelingAnnounceTargetChannel LevelingAnnounceTarget = "channel"
	LevelingAnnounceTargetDM      LevelingAnnounceTarget = "dm"
)

// LevelingRewardStacking espeja `LevelingRewardStacking` — qué pasa con los
// roles de recompensa anteriores al subir de nivel: `stack` los conserva
// todos, `replace` quita el del nivel previo.
type LevelingRewardStacking string

const (
	LevelingRewardStackingStack   LevelingRewardStacking = "stack"
	LevelingRewardStackingReplace LevelingRewardStacking = "replace"
)

// LevelingCardMode espeja `LevelingCardMode` — mismo par que
// `GreeterImageMode`: `basic` es la tarjeta de fábrica (fondo + acento),
// `advanced` es el lienzo del editor.
type LevelingCardMode string

const (
	LevelingCardBasic    LevelingCardMode = "basic"
	LevelingCardAdvanced LevelingCardMode = "advanced"
)

// LevelingAccessMode espeja `DBAccessMode` (`"only" | "all_except"`): `only`
// es lista blanca, `all_except` lista negra.
type LevelingAccessMode string

const (
	LevelingAccessOnly      LevelingAccessMode = "only"
	LevelingAccessAllExcept LevelingAccessMode = "all_except"
)

// LevelingXpSource mirrors `DBLevelingXpSource` — una fuente de XP (texto o
// voz). `IntervalSeconds` significa cosas distintas en cada una y por eso NO
// se llama `Cooldown`: en texto es la ventana antispam (sólo el primer
// mensaje de la ventana da XP); en voz es la duración del tick (cada tick
// completo en voz concede una tirada).
type LevelingXpSource struct {
	Enabled         bool `bson:"enabled"          json:"enabled"`
	Min             int  `bson:"min"              json:"min"`
	Max             int  `bson:"max"              json:"max"`
	IntervalSeconds int  `bson:"interval_seconds" json:"interval_seconds"`
}

// LevelingMultiplier mirrors `DBLevelingMultiplier` — multiplicador de XP
// atado a un rol o a un canal, según la lista en la que viva.
type LevelingMultiplier struct {
	ID         string  `bson:"id"         json:"id"`
	Multiplier float64 `bson:"multiplier" json:"multiplier"`
}

// LevelingReward mirrors `DBLevelingReward` — al alcanzar `Level` se
// conceden estos roles.
type LevelingReward struct {
	Level   int      `bson:"level"    json:"level"`
	RoleIDs []string `bson:"role_ids" json:"role_ids"`
}

// LevelingVoiceRules mirrors el objeto inline `ModuleLeveling.voice_rules`
// de la interfaz TS — cuándo NO cuenta el tiempo en voz.
type LevelingVoiceRules struct {
	IgnoreAlone    bool `bson:"ignore_alone"    json:"ignore_alone"`
	IgnoreMuted    bool `bson:"ignore_muted"    json:"ignore_muted"`
	IgnoreDeafened bool `bson:"ignore_deafened" json:"ignore_deafened"`
}

// LevelingAnnounce mirrors el objeto inline `ModuleLeveling.announce` de la
// interfaz TS. `Content` es un CENTINELA (ver `NewModuleLeveling` en el
// paquete `mocks`): mientras el guild lo tenga byte a byte igual al default
// de fábrica, bot y dashboard lo traducen con la clave i18n
// `announceDefault` — igual que `DEFAULT_TEMPVOICE_PANEL`.
type LevelingAnnounce struct {
	Enabled            bool                   `bson:"enabled"              json:"enabled"`
	Target             LevelingAnnounceTarget `bson:"target"               json:"target"`
	ChannelID          *string                `bson:"channel_id"           json:"channel_id"`
	Content            string                 `bson:"content"              json:"content"`
	DeleteAfterSeconds *int                   `bson:"delete_after_seconds" json:"delete_after_seconds"`
}

// LevelingRewards mirrors el objeto inline `ModuleLeveling.rewards` de la
// interfaz TS.
type LevelingRewards struct {
	Enabled  bool                    `bson:"enabled"  json:"enabled"`
	Stacking LevelingRewardStacking  `bson:"stacking" json:"stacking"`
	Levels   []LevelingReward        `bson:"levels"   json:"levels"`
}

// LevelingRankCard mirrors el objeto inline `ModuleLeveling.rank_card` de la
// interfaz TS. `Canvas` reutiliza `GreeterImageCanvas` tal cual — mismo
// lienzo que greeter, incluida la capa `bar` (ver el comentario de
// `GreeterImageElement.BarToken`).
type LevelingRankCard struct {
	Mode          LevelingCardMode   `bson:"mode"           json:"mode"`
	BackgroundURL *string            `bson:"background_url" json:"background_url"`
	AccentColor   string             `bson:"accent_color"   json:"accent_color"`
	Canvas        GreeterImageCanvas `bson:"canvas"         json:"canvas"`
}

// LevelingAccessList mirrors `DBAccessList` — la lista de acceso de un eje
// (roles/canales/categorías) del comando `rank`.
type LevelingAccessList struct {
	Mode LevelingAccessMode `bson:"mode" json:"mode"`
	IDs  []string           `bson:"ids"  json:"ids"`
}

// LevelingCommandAccess mirrors `DBCommandAccess` — acceso por eje (quién:
// roles, dónde: canales/categorías) del comando `rank`.
type LevelingCommandAccess struct {
	Roles      LevelingAccessList `bson:"roles"      json:"roles"`
	Channels   LevelingAccessList `bson:"channels"   json:"channels"`
	Categories LevelingAccessList `bson:"categories" json:"categories"`
}

// LevelingCommandSync mirrors el objeto inline `DBLevelingCommand.use_global`
// de la interfaz TS — herencia POR EJE del acceso global. Un eje en `true`
// lee de `commands_global`; en `false`, del `access` propio del comando.
// A diferencia de tempvoice/music, aquí no hace falta `UnmarshalJSON` para
// el booleano legacy: el módulo nace ya con la forma por eje, no existe
// ningún documento anterior que migrar.
type LevelingCommandSync struct {
	Roles      bool `bson:"roles"      json:"roles"`
	Channels   bool `bson:"channels"   json:"channels"`
	Categories bool `bson:"categories" json:"categories"`
}

// LevelingCommand mirrors `DBLevelingCommand` — gemelo de
// `DBTempVoiceCommand`/`TempvoiceCommand`, config del único comando
// configurable del módulo (`rank`).
type LevelingCommand struct {
	Enabled   bool                   `bson:"enabled"    json:"enabled"`
	UseGlobal LevelingCommandSync    `bson:"use_global" json:"use_global"`
	Access    LevelingCommandAccess  `bson:"access"     json:"access"`
}

// ModuleLeveling matches `DBModuleLeveling`. Field order sigue la interfaz TS
// (no hay zod schema de Node del que copiar el orden — igual que tickets).
type ModuleLeveling struct {
	SchemaVersion int  `bson:"schema_version" json:"schema_version"`
	Enabled       bool `bson:"enabled"        json:"enabled"`
	// EnabledSince es la fecha de la PRIMERA activación del módulo en este
	// guild — WRITE-ONCE: se estampa al activar por primera vez y no se
	// reescribe nunca (ni al desactivar ni al reactivar). `nil` (campo
	// ausente en Mongo) = nunca activado. Mismo contrato que
	// `ModuleTempvoice.EnabledSince` / `ModuleTickets.EnabledSince`.
	EnabledSince       *JSONDate                  `bson:"enabled_since,omitempty" json:"enabled_since"`
	XPMode             LevelingXPMode             `bson:"xp_mode"              json:"xp_mode"`
	Text               LevelingXpSource           `bson:"text"                 json:"text"`
	Voice              LevelingXpSource           `bson:"voice"                json:"voice"`
	CurveMultiplier    float64                    `bson:"curve_multiplier"     json:"curve_multiplier"`
	VoiceRules         LevelingVoiceRules         `bson:"voice_rules"          json:"voice_rules"`
	ExcludedChannelIDs []string                   `bson:"excluded_channel_ids" json:"excluded_channel_ids"`
	ExcludedRoleIDs    []string                   `bson:"excluded_role_ids"    json:"excluded_role_ids"`
	RoleMultipliers    []LevelingMultiplier       `bson:"role_multipliers"     json:"role_multipliers"`
	ChannelMultipliers []LevelingMultiplier       `bson:"channel_multipliers"  json:"channel_multipliers"`
	Announce           LevelingAnnounce           `bson:"announce"             json:"announce"`
	Rewards            LevelingRewards            `bson:"rewards"              json:"rewards"`
	RankCard           LevelingRankCard           `bson:"rank_card"            json:"rank_card"`
	CommandsGlobal     LevelingCommandAccess      `bson:"commands_global"      json:"commands_global"`
	Commands           map[string]LevelingCommand `bson:"commands"             json:"commands"`
	CommandMode        LevelingCommandMode        `bson:"command_mode"         json:"command_mode"`
	UpdatedAt          JSONDate                   `bson:"updated_at"           json:"updated_at"`
}

// NormalizeLeveling rellena todo campo de colección que haya decodificado
// `nil` (de un documento parcial de Mongo o una entrada de caché vieja) con
// un valor vacío no-nil, para que el cuerpo JSON emita `[]`/`{}` en vez de
// `null`. Los escalares y los punteros nullable NO se tocan: un `null`
// almacenado sigue siendo `null`. Idempotente.
func NormalizeLeveling(m *ModuleLeveling) {
	if m == nil {
		return
	}

	m.ExcludedChannelIDs = ensureStrSlice(m.ExcludedChannelIDs)
	m.ExcludedRoleIDs = ensureStrSlice(m.ExcludedRoleIDs)
	m.RoleMultipliers = ensureLevelingMultiplierSlice(m.RoleMultipliers)
	m.ChannelMultipliers = ensureLevelingMultiplierSlice(m.ChannelMultipliers)

	m.Rewards.Levels = ensureLevelingRewardSlice(m.Rewards.Levels)
	for i := range m.Rewards.Levels {
		m.Rewards.Levels[i].RoleIDs = ensureStrSlice(m.Rewards.Levels[i].RoleIDs)
	}

	if m.RankCard.Canvas.Elements == nil {
		m.RankCard.Canvas.Elements = []GreeterImageElement{}
	}

	normalizeLevelingAccess(&m.CommandsGlobal)

	if m.Commands == nil {
		m.Commands = map[string]LevelingCommand{}
	} else {
		for k, v := range m.Commands {
			normalizeLevelingAccess(&v.Access)
			m.Commands[k] = v
		}
	}
}

// normalizeLevelingAccess rellena las tres listas de IDs de un bloque de
// acceso por comando para que cada una serialice como `[]`.
func normalizeLevelingAccess(a *LevelingCommandAccess) {
	a.Roles.IDs = ensureStrSlice(a.Roles.IDs)
	a.Channels.IDs = ensureStrSlice(a.Channels.IDs)
	a.Categories.IDs = ensureStrSlice(a.Categories.IDs)
}

func ensureLevelingMultiplierSlice(s []LevelingMultiplier) []LevelingMultiplier {
	if s == nil {
		return []LevelingMultiplier{}
	}
	return s
}

func ensureLevelingRewardSlice(s []LevelingReward) []LevelingReward {
	if s == nil {
		return []LevelingReward{}
	}
	return s
}

