package validations

import (
	"kena.bot/api-db-go/internal/domain/dbguild"
)

// UpdateModuleLevelingBody es el cuerpo PATCH estricto del módulo de
// niveles — mismo molde que `UpdateModuleTempvoiceBody`: todos los campos
// son punteros para que el decodificador estricto (`DisallowUnknownFields`)
// valide la forma mientras la PRESENCIA de la clave sobrevive para el merge
// `MergeDeepJSON` del repositorio: una clave ausente en el body no se toca;
// un `false`/`0`/`""`/`null` explícito se aplica y pisa el valor guardado;
// los objetos anidados recursan (un PATCH parcial de `{"text":{"min":10}}`
// conserva el resto de `text` intacto); el único mapa (`commands`) mezcla
// por clave.
//
// `schema_version`, `enabled_since` y `updated_at` quedan FUERA a propósito
// — son gestionados por el servidor (mismo criterio que
// `UpdateModuleTempvoiceBody`: `enabled_since` es WRITE-ONCE y ni siquiera se
// acepta como clave, así que un cliente que la mande recibe 400 por clave
// desconocida en vez de que se ignore en silencio).
type UpdateModuleLevelingBody struct {
	Enabled            *bool                                `json:"enabled,omitempty"`
	XPMode             *dbguild.LevelingXPMode              `json:"xp_mode,omitempty"`
	Text               *dbguild.LevelingXpSource            `json:"text,omitempty"`
	Voice              *dbguild.LevelingXpSource            `json:"voice,omitempty"`
	CurveMultiplier    *float64                             `json:"curve_multiplier,omitempty"`
	VoiceRules         *dbguild.LevelingVoiceRules          `json:"voice_rules,omitempty"`
	ExcludedChannelIDs *[]string                            `json:"excluded_channel_ids,omitempty"`
	ExcludedRoleIDs    *[]string                            `json:"excluded_role_ids,omitempty"`
	RoleMultipliers    *[]dbguild.LevelingMultiplier        `json:"role_multipliers,omitempty"`
	ChannelMultipliers *[]dbguild.LevelingMultiplier        `json:"channel_multipliers,omitempty"`
	Announce           *dbguild.LevelingAnnounce            `json:"announce,omitempty"`
	Rewards            *dbguild.LevelingRewards             `json:"rewards,omitempty"`
	RankCard           *dbguild.LevelingRankCard            `json:"rank_card,omitempty"`
	CommandsGlobal     *dbguild.LevelingCommandAccess        `json:"commands_global,omitempty"`
	Commands           *map[string]dbguild.LevelingCommand   `json:"commands,omitempty"`
	CommandMode        *dbguild.LevelingCommandMode          `json:"command_mode,omitempty"`
}

package handlers

import (
	"bytes"
	"encoding/json"

	"github.com/gofiber/fiber/v3"

	"kena.bot/api-db-go/internal/domain/dbguild"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
	"kena.bot/api-db-go/internal/domain/validations"
	"kena.bot/api-db-go/internal/infrastructure/mongorepo"
	"kena.bot/api-db-go/internal/shared/result"
)

// sourceDetailLevelingDBNotFound es el detalle de fuente estampado en el
// envelope de "no encontrado" del PATCH (el repo devuelve un `nil` a secas
// ahí, así que el handler no tiene un `Sourced` del que leerlo). Se
// mantiene en paralelo con `mongo.SourceDetailModuleLevelingDB` — el
// handler no puede importar el paquete de infraestructura mongo sin violar
// las capas, así que el string se duplica localmente. Mismo patrón que
// `sourceDetailTicketsDBNotFound`.
const sourceDetailLevelingDBNotFound = "mongo.guild.module_leveling"

// ModuleLevelingHandler cablea los dos endpoints de niveles (GET/PATCH
// scoped a guild) tras un único struct. Espeja al handler de tickets:
// payload `*dbguild.ModuleLeveling` para que los caminos "no encontrado"
// emitan `"data":null`, sin pre-chequeo de guild (una guild ausente da
// MODULE_NOT_FOUND, no GUILD_NOT_FOUND).
type ModuleLevelingHandler struct {
	Repo mongorepo.ModuleLevelingRepo
}

// NewModuleLevelingHandler construye el handler.
func NewModuleLevelingHandler(repo mongorepo.ModuleLevelingRepo) *ModuleLevelingHandler {
	return &ModuleLevelingHandler{Repo: repo}
}

// Get devuelve el subdocumento de niveles completo (con defaults y
// normalizado) con las cabeceras de fuente estampadas, o un 400
// MODULE_NOT_FOUND con `data:null` + fuente cuando la guild todavía no
// tiene config de niveles.
func (h *ModuleLevelingHandler) Get(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleLeveling]()
	ctx := c.Context()

	sourced, err := h.Repo.FindModule(ctx, c.Params("bot_id"), c.Params("guild_id"))
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}
	if sourced != nil {
		r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	}
	if sourced == nil || sourced.Data.SchemaVersion == 0 {
		r.SetData(nil)
		r.AddError(apierrors.MongoMessage("Module not found", apierrors.CodeModuleNotFound))
		return reply(c, r)
	}
	d := sourced.Data
	r.SetData(&d)
	return reply(c, r)
}

// Patch valida el body estricto (`DisallowUnknownFields`), lo redecodifica
// como `map[string]any` para que la PRESENCIA de claves sobreviva, y el
// repo lo mezcla con `MergeDeepJSON` sobre el subdocumento actual. Un body
// vacío `{}` es un no-op que igualmente bumpea `schema_version`. Una guild
// ausente → 400 MODULE_NOT_FOUND con `data:null`.
func (h *ModuleLevelingHandler) Patch(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleLeveling]()
	ctx := c.Context()

	var body validations.UpdateModuleLevelingBody
	dec := json.NewDecoder(bytes.NewReader(c.Body()))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&body); err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	patch, err := patchMap(c.Body())
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	sourced, err := h.Repo.Update(ctx, c.Params("bot_id"), c.Params("guild_id"), patch)
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}
	if sourced == nil || sourced.Data.SchemaVersion == 0 {
		r.SetSource(result.SourceDB, sourceDetailLevelingDBNotFound)
		r.SetData(nil)
		r.AddError(apierrors.MongoMessage("Module not found", apierrors.CodeModuleNotFound))
		return reply(c, r)
	}
	d := sourced.Data
	r.SetData(&d)
	r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	return reply(c, r)
}

package validations

import (
	"kena.bot/api-db-go/internal/domain/dbguild"
)

// UpdateModuleTempvoiceBody mirrors the Node `updateModuleTempVoiceSchema` (a
// `.strict()` object of `.optional()` fields). Unlike the READ schema, the
// PATCH schema excludes only `schema_version` and `updated_at` (server-managed).
// The top-level `name_blacklist`, `panel` and `command_mode` (added in v3/v4/v7)
// ARE patchable — omitting them here made the strict decoder reject them as
// `unrecognized_keys` on any PATCH that included them (e.g. saving the panel from
// the dashboard) → 400. Every field is a pointer so the strict decoder can validate
// the shape; the handler then re-decodes the SAME raw body as `map[string]any`,
// which the repository merges into the existing subdoc via
// `mongo.MergeDeepJSON` by KEY PRESENCE: a key absent in the body is left
// alone; an explicit `false`/`0`/`""`/`null` is applied and overrides the
// stored value; nested objects recurse (so a partial
// `{"defaults":{"bitrate":96000}}` PATCH preserves the other defaults);
// slices (`creators`) replace wholesale; maps merge per-key.
//
// PER OLA-3 NOTE: the greeter/logs/music bodies bind via Fiber's default
// decoder (silently drops unknown keys, parity with Mongoose) — only
// modmail/tempvoice/giveaway/moderation carry the strict unknown-key
// rejection. The nested field types are the full `dbguild.Tempvoice*`
// shapes: every zod PATCH sub-schema matches its parent type
// field-for-field, so no valid key is rejected. Go's json decoder does
// NOT enforce zod's REQUIRED-ness inside a present nested object, so a
// partial command entry that Node would 400 is accepted here and the
// missing leaves stay zero — the same non-strict-required behaviour
// every Go module body has.
type UpdateModuleTempvoiceBody struct {
	Enabled        *bool                                `json:"enabled,omitempty"`
	Creators       *[]dbguild.TempvoiceCreator          `json:"creators,omitempty"`
	NameBlacklist  *[]string                            `json:"name_blacklist,omitempty"`
	Panel          *dbguild.TempvoicePanel              `json:"panel,omitempty"`
	CommandMode    *dbguild.TempvoiceCommandMode        `json:"command_mode,omitempty"`
	Defaults       *dbguild.TempvoiceDefaults           `json:"defaults,omitempty"`
	CommandsGlobal *dbguild.TempvoiceCommandAccess      `json:"commands_global,omitempty"`
	Commands       *map[string]dbguild.TempvoiceCommand `json:"commands,omitempty"`
}

package validations

import (
	"encoding/json"
	"fmt"
	"math"
	"strconv"
	"strings"

	"kena.bot/api-db-go/internal/domain/dbleveling"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
)

// Request DTOs + parsers para las seis rutas `/leveling/bots/:bot_id/guilds/:guild_id/**`
// (§8 del contrato). Vertical NUEVA sin contraparte en el Node api-db, así
// que no hay un zod que mirrorear byte a byte — pero, a diferencia del resto
// del paquete (moderation_flow_runs_validations.go, etc.), esta vertical
// NUNCA responde 400 por un `scope`, `curve_multiplier`, delta de XP,
// `limit` u `offset` ausente o mal formado: el propio contrato lo pide
// explícito para curve_multiplier ("si falta o no es válido, default 1") y
// aquí se aplica el MISMO criterio a los otros cuatro, porque los cinco son
// parámetros de LECTURA/ESCRITURA DERIVADA (§3), no validaciones de
// negocio — el repositorio ya clampa limit/offset a sus rangos (ver
// LevelingRepository.Top). El único 400 real de esta vertical es
// `user_id` ausente dentro de una entrada de `POST /xp/bulk` (no tiene
// default razonable) o un body que ni siquiera es JSON válido.
//
// Reusa los helpers compartidos del paquete: parseRequiredString,
// bodyBindError, isJSONNull (definidos en otros ficheros de este mismo
// paquete).

// levelingDefaultTopLimit es el default de `limit` en GET .../top cuando el
// query param falta o no es numérico — no lo fija el contrato, pero es el
// tamaño habitual de un leaderboard "top". El repositorio clampa el valor
// final (venga de aquí o del cliente) a [1,100].
const levelingDefaultTopLimit = 10

// parseLevelingInt intenta leer `raw` como entero; ausente o no numérico →
// `def`. Sin validación estricta a propósito (ver el comentario de
// package): limit/offset son parámetros de lectura derivada y el
// repositorio ya los clampa a su rango válido.
func parseLevelingInt(raw string, def int) int {
	if raw == "" {
		return def
	}
	v, err := strconv.Atoi(strings.TrimSpace(raw))
	if err != nil {
		return def
	}
	return v
}

// parseLevelingCurveMultiplier interpreta el query param `curve_multiplier`:
// ausente, no numérico, no-positivo, NaN o infinito → 1 (el default de
// DBModuleLeveling — §8: "si falta o no es válido, default 1"). Nunca
// produce un 400.
func parseLevelingCurveMultiplier(raw string) float64 {
	if raw == "" {
		return 1
	}
	v, err := strconv.ParseFloat(strings.TrimSpace(raw), 64)
	if err != nil || v <= 0 || math.IsNaN(v) || math.IsInf(v, 0) {
		return 1
	}
	return v
}

// parseLevelingCurveMultiplierBody es el equivalente de
// parseLevelingCurveMultiplier para el campo `curve_multiplier` del body
// (POST /users/:user_id/xp y POST /xp/bulk) — mismo default, mismas
// condiciones de invalidez.
func parseLevelingCurveMultiplierBody(raw json.RawMessage) float64 {
	if raw == nil || isJSONNull(raw) {
		return 1
	}
	var v float64
	if err := json.Unmarshal(raw, &v); err != nil || v <= 0 || math.IsNaN(v) || math.IsInf(v, 0) {
		return 1
	}
	return v
}

// parseLevelingNonNegInt64 interpreta un delta de XP del body (text_xp,
// voice_xp, messages, voice_seconds): ausente o null → 0; negativo o de
// otro tipo → 0 (clampeado, nunca 400 — ver el comentario de package); si
// no, el entero (truncado si llega con decimales).
func parseLevelingNonNegInt64(raw json.RawMessage) int64 {
	if raw == nil || isJSONNull(raw) {
		return 0
	}
	var v float64
	if err := json.Unmarshal(raw, &v); err != nil || v < 0 {
		return 0
	}
	return int64(v)
}

// parseLevelingBool interpreta `touch_message`: ausente, null o cualquier
// valor no-booleano → false.
func parseLevelingBool(raw json.RawMessage) bool {
	if raw == nil || isJSONNull(raw) {
		return false
	}
	var b bool
	if err := json.Unmarshal(raw, &b); err != nil {
		return false
	}
	return b
}

// ─── GET /leveling/bots/:bot_id/guilds/:guild_id/top ──────────────────────

// ParseLevelingTopQuery mirrors la query de GET .../top: `scope` (default
// "unified" — dbleveling.NormalizeScope), `curve_multiplier` (default 1),
// `limit` (default levelingDefaultTopLimit, el repositorio clampa a
// [1,100]), `offset` (default 0, el repositorio clampa a >=0).
func ParseLevelingTopQuery(scope, curveMultiplierRaw, limitRaw, offsetRaw string) (normScope string, curveMultiplier float64, limit, offset int) {
	return dbleveling.NormalizeScope(scope),
		parseLevelingCurveMultiplier(curveMultiplierRaw),
		parseLevelingInt(limitRaw, levelingDefaultTopLimit),
		parseLevelingInt(offsetRaw, 0)
}

// ─── GET /leveling/bots/:bot_id/guilds/:guild_id/users/:user_id ───────────

// ParseLevelingUserQuery mirrors la query de GET .../users/:user_id:
// `scope` (default "unified"), `curve_multiplier` (default 1).
func ParseLevelingUserQuery(scope, curveMultiplierRaw string) (normScope string, curveMultiplier float64) {
	return dbleveling.NormalizeScope(scope), parseLevelingCurveMultiplier(curveMultiplierRaw)
}

// ─── POST /leveling/bots/:bot_id/guilds/:guild_id/users/:user_id/xp ───────

// ParseLevelingAddXP mirrors el body de POST .../users/:user_id/xp:
// `{text_xp?, voice_xp?, messages?, voice_seconds?, curve_multiplier?,
// touch_message?}` — TODOS opcionales. Un body vacío (`{}`, `null`, o
// ausente) es válido: los cuatro deltas quedan a 0, que es el "touch" del
// §3 (re-deriva y persiste los niveles de este miembro sin conceder XP).
// El único error posible es un body que ni siquiera es JSON válido.
func ParseLevelingAddXP(body []byte) (dbleveling.AddXPInput, *apierrors.CustomError) {
	var raw struct {
		TextXP          json.RawMessage `json:"text_xp"`
		VoiceXP         json.RawMessage `json:"voice_xp"`
		Messages        json.RawMessage `json:"messages"`
		VoiceSeconds    json.RawMessage `json:"voice_seconds"`
		CurveMultiplier json.RawMessage `json:"curve_multiplier"`
		TouchMessage    json.RawMessage `json:"touch_message"`
	}
	if len(body) > 0 {
		if err := json.Unmarshal(body, &raw); err != nil {
			return dbleveling.AddXPInput{}, bodyBindError(err)
		}
	}
	return dbleveling.AddXPInput{
		TextXP:          parseLevelingNonNegInt64(raw.TextXP),
		VoiceXP:         parseLevelingNonNegInt64(raw.VoiceXP),
		Messages:        parseLevelingNonNegInt64(raw.Messages),
		VoiceSeconds:    parseLevelingNonNegInt64(raw.VoiceSeconds),
		CurveMultiplier: parseLevelingCurveMultiplierBody(raw.CurveMultiplier),
		TouchMessage:    parseLevelingBool(raw.TouchMessage),
	}, nil
}

// ─── POST /leveling/bots/:bot_id/guilds/:guild_id/xp/bulk ─────────────────

// ParseLevelingAddXPBulk mirrors el body de POST .../xp/bulk:
// `{entries: [{user_id, text_xp?, voice_xp?, messages?, voice_seconds?,
// touch_message?}], curve_multiplier?}`. `user_id` es el ÚNICO campo
// REQUERIDO de todo este endpoint — dentro de cada entrada, no tiene un
// default razonable — y falla con el índice exacto en la property
// (`entries.N.user_id`) para señalar la fila. `entries` ausente o vacío es
// válido: el repositorio lo trata como no-op. `curve_multiplier` es
// COMPARTIDO por todo el lote (§8), no por entrada.
func ParseLevelingAddXPBulk(body []byte) ([]dbleveling.BulkEntry, float64, *apierrors.CustomError) {
	var raw struct {
		Entries []struct {
			UserID       json.RawMessage `json:"user_id"`
			TextXP       json.RawMessage `json:"text_xp"`
			VoiceXP      json.RawMessage `json:"voice_xp"`
			Messages     json.RawMessage `json:"messages"`
			VoiceSeconds json.RawMessage `json:"voice_seconds"`
			TouchMessage json.RawMessage `json:"touch_message"`
		} `json:"entries"`
		CurveMultiplier json.RawMessage `json:"curve_multiplier"`
	}
	if len(body) > 0 {
		if err := json.Unmarshal(body, &raw); err != nil {
			return nil, 1, bodyBindError(err)
		}
	}

	entries := make([]dbleveling.BulkEntry, 0, len(raw.Entries))
	for i, e := range raw.Entries {
		userID, verr := parseRequiredString(e.UserID, fmt.Sprintf("entries.%d.user_id", i), 1, 32)
		if verr != nil {
			return nil, 1, verr
		}
		entries = append(entries, dbleveling.BulkEntry{
			UserID:       userID,
			TextXP:       parseLevelingNonNegInt64(e.TextXP),
			VoiceXP:      parseLevelingNonNegInt64(e.VoiceXP),
			Messages:     parseLevelingNonNegInt64(e.Messages),
			VoiceSeconds: parseLevelingNonNegInt64(e.VoiceSeconds),
			TouchMessage: parseLevelingBool(e.TouchMessage),
		})
	}
	return entries, parseLevelingCurveMultiplierBody(raw.CurveMultiplier), nil
}

