// LevelingRequirements mirrors `DBLevelingRequirements` — requisitos de
// elegibilidad para ganar XP con una fuente, pensados para el abuso, no para
// la burocracia: el caso que los motiva es la cuenta recién creada que entra,
// farmea nivel a base de mensajes de una letra y se va. Todo entero es
// segundos/caracteres con `0` = sin requisito; los cuatro `Ignore*` son
// SOLO TEXTO y se persisten igual en el bloque de voz por simetría de forma
// (mismo criterio que `LevelingVoiceRules` en el bloque de texto).
type LevelingRequirements struct {
	// MinMembershipSeconds: segundos que el miembro debe llevar EN EL
	// SERVIDOR antes de ganar XP. Sale de `joined_at`, que ya está en la
	// caché de miembros: ninguna petición extra a Discord.
	MinMembershipSeconds int `bson:"min_membership_seconds" json:"min_membership_seconds"`
	// MinAccountAgeSeconds: antigüedad mínima de la CUENTA de Discord. Se
	// deduce del snowflake del propio id de usuario, tampoco cuesta ninguna
	// petición.
	MinAccountAgeSeconds int `bson:"min_account_age_seconds" json:"min_account_age_seconds"`
	// MinMessageLength: SOLO TEXTO. Caracteres mínimos del mensaje, ya
	// recortado.
	MinMessageLength int `bson:"min_message_length" json:"min_message_length"`
	// IgnoreLinkOnly: SOLO TEXTO. Descarta el mensaje cuyo contenido,
	// quitado el enlace, queda vacío.
	IgnoreLinkOnly bool `bson:"ignore_link_only" json:"ignore_link_only"`
	// IgnoreAttachmentOnly: SOLO TEXTO. Descarta el mensaje sin texto que
	// solo trae adjuntos.
	IgnoreAttachmentOnly bool `bson:"ignore_attachment_only" json:"ignore_attachment_only"`
	// IgnoreStickerOrEmojiOnly: SOLO TEXTO. Descarta el mensaje que solo son
	// emojis (unicode o custom) o un sticker.
	IgnoreStickerOrEmojiOnly bool `bson:"ignore_sticker_or_emoji_only" json:"ignore_sticker_or_emoji_only"`
	// IgnoreCommands: SOLO TEXTO. Descarta el mensaje que empieza por el
	// prefijo del servidor.
	IgnoreCommands bool `bson:"ignore_commands" json:"ignore_commands"`
	// BypassRoleIDs: roles que se saltan TODOS los requisitos anteriores
	// (staff, boosters…).
	BypassRoleIDs []string `bson:"bypass_role_ids" json:"bypass_role_ids"`
}

