package dbguild

// Este fichero es el espejo de `DBModuleLeveling` en
// `libraries/library-shared/src/db/schemas/DBGuildSchemas.ts`. Como con
// tickets, el módulo de niveles no tiene contrapartida en ningún zod schema
// de Node — nace directamente en api-db-go y en el dashboard —, así que el
// ORDEN de los campos sigue al del interfaz de TypeScript tal cual, no a un
// schema-definition ajeno.
//
// Los campos nullable (`string | null`, `number | null` en TS) usan punteros
// para que la codificación JSON emita `null` (nunca el cero del tipo) en la
// variante sin valor. Los campos de colección (`[]string`, `Record<...>`)
// NUNCA llevan `omitempty`: un valor presente-pero-vacío tiene que serializar
// como `[]` / `{}`, jamás `null`. `NormalizeLeveling` rellena las colecciones
// que decodifican `nil` para sostener ese invariante en los documentos leídos
// de Mongo/Redis.
//
// El histórico de XP en sí (mensajes, tiempo en voz, niveles por miembro) NO
// vive aquí: vive en Postgres (`leveling.user_stats`, ver
// `internal/infrastructure/postgres/leveling_repository.go`). Este
// subdocumento es SOLO la configuración por-guild.

// LevelingXPMode espeja `LevelingXpMode`: el almacenamiento SIEMPRE guarda XP
// de texto y de voz por separado (ver `ModuleLeveling.Text`/`.Voice`); este
// campo es una decisión de LECTURA, no de escritura — "unified" deriva nivel
// y rank de `text_xp + voice_xp`, "separate" lleva progresión propia de cada
// fuente. Cambiar el modo nunca destruye datos.
type LevelingXPMode string

const (
	LevelingXPModeUnified  LevelingXPMode = "unified"
	LevelingXPModeSeparate LevelingXPMode = "separate"
)

// LevelingCommandMode espeja `LevelingCommandMode` — mismo patrón que
// `TempvoiceCommandMode`: cómo se puede invocar el (único) comando del
// módulo, `rank`.
type LevelingCommandMode string

const (
	LevelingCommandModeSlash  LevelingCommandMode = "slash"
	LevelingCommandModePrefix LevelingCommandMode = "prefix"
	LevelingCommandModeBoth   LevelingCommandMode = "both"
)

// LevelingAnnounceTarget espeja `LevelingAnnounceTarget` — dónde se publica
// el anuncio de subida de nivel.
type LevelingAnnounceTarget string

const (
	LevelingAnnounceTargetCurrent LevelingAnnounceTarget = "current"
	LevelingAnnounceTargetChannel LevelingAnnounceTarget = "channel"
	LevelingAnnounceTargetDM      LevelingAnnounceTarget = "dm"
)

// LevelingRewardStacking espeja `LevelingRewardStacking` — qué pasa con los
// roles de recompensa anteriores al subir de nivel: `stack` los conserva
// todos, `replace` quita el del nivel previo.
type LevelingRewardStacking string

const (
	LevelingRewardStackingStack   LevelingRewardStacking = "stack"
	LevelingRewardStackingReplace LevelingRewardStacking = "replace"
)

// LevelingCardMode espeja `LevelingCardMode` — mismo par que
// `GreeterImageMode`: `basic` es la tarjeta de fábrica (fondo + acento),
// `advanced` es el lienzo del editor.
type LevelingCardMode string

const (
	LevelingCardBasic    LevelingCardMode = "basic"
	LevelingCardAdvanced LevelingCardMode = "advanced"
)

// LevelingAccessMode espeja `DBAccessMode` (`"only" | "all_except"`): `only`
// es lista blanca, `all_except` lista negra.
type LevelingAccessMode string

const (
	LevelingAccessOnly      LevelingAccessMode = "only"
	LevelingAccessAllExcept LevelingAccessMode = "all_except"
)

// LevelingXpSource mirrors `DBLevelingXpSource` — una fuente de XP (texto o
// voz). `IntervalSeconds` significa cosas distintas en cada una y por eso NO
// se llama `Cooldown`: en texto es la ventana antispam (sólo el primer
// mensaje de la ventana da XP); en voz es la duración del tick (cada tick
// completo en voz concede una tirada).
type LevelingXpSource struct {
	Enabled         bool `bson:"enabled"          json:"enabled"`
	Min             int  `bson:"min"              json:"min"`
	Max             int  `bson:"max"              json:"max"`
	IntervalSeconds int  `bson:"interval_seconds" json:"interval_seconds"`
}

// LevelingMultiplier mirrors `DBLevelingMultiplier` — multiplicador de XP
// atado a un rol o a un canal, según la lista en la que viva.
type LevelingMultiplier struct {
	ID         string  `bson:"id"         json:"id"`
	Multiplier float64 `bson:"multiplier" json:"multiplier"`
}

// LevelingReward mirrors `DBLevelingReward` — al alcanzar `Level` se
// conceden estos roles.
type LevelingReward struct {
	Level   int      `bson:"level"    json:"level"`
	RoleIDs []string `bson:"role_ids" json:"role_ids"`
}

// LevelingVoiceRules mirrors el objeto inline `ModuleLeveling.voice_rules`
// de la interfaz TS — cuándo NO cuenta el tiempo en voz.
type LevelingVoiceRules struct {
	IgnoreAlone    bool `bson:"ignore_alone"    json:"ignore_alone"`
	IgnoreMuted    bool `bson:"ignore_muted"    json:"ignore_muted"`
	IgnoreDeafened bool `bson:"ignore_deafened" json:"ignore_deafened"`
}

// LevelingAnnounce mirrors el objeto inline `ModuleLeveling.announce` de la
// interfaz TS. `Content` es un CENTINELA (ver `NewModuleLeveling` en el
// paquete `mocks`): mientras el guild lo tenga byte a byte igual al default
// de fábrica, bot y dashboard lo traducen con la clave i18n
// `announceDefault` — igual que `DEFAULT_TEMPVOICE_PANEL`.
type LevelingAnnounce struct {
	Enabled            bool                   `bson:"enabled"              json:"enabled"`
	Target             LevelingAnnounceTarget `bson:"target"               json:"target"`
	ChannelID          *string                `bson:"channel_id"           json:"channel_id"`
	Content            string                 `bson:"content"              json:"content"`
	DeleteAfterSeconds *int                   `bson:"delete_after_seconds" json:"delete_after_seconds"`
}

// LevelingRewards mirrors el objeto inline `ModuleLeveling.rewards` de la
// interfaz TS.
type LevelingRewards struct {
	Enabled  bool                    `bson:"enabled"  json:"enabled"`
