	EnabledSince       *JSONDate                  `bson:"enabled_since,omitempty" json:"enabled_since"`
	XPMode             LevelingXPMode             `bson:"xp_mode"              json:"xp_mode"`
	Text               LevelingXpSource           `bson:"text"                 json:"text"`
