// `null`. Los escalares y los punteros nullable NO se tocan: un `null`
// almacenado sigue siendo `null`. Idempotente.
func NormalizeLeveling(m *ModuleLeveling) {
	if m == nil {
		return
	}

	m.ExcludedChannelIDs = ensureStrSlice(m.ExcludedChannelIDs)
	m.ExcludedRoleIDs = ensureStrSlice(m.ExcludedRoleIDs)
	m.RoleMultipliers = ensureLevelingMultiplierSlice(m.RoleMultipliers)
	m.ChannelMultipliers = ensureLevelingMultiplierSlice(m.ChannelMultipliers)

	m.Rewards.Levels = ensureLevelingRewardSlice(m.Rewards.Levels)
	for i := range m.Rewards.Levels {
		m.Rewards.Levels[i].RoleIDs = ensureStrSlice(m.Rewards.Levels[i].RoleIDs)
	}

	if m.RankCard.Canvas.Elements == nil {
		m.RankCard.Canvas.Elements = []GreeterImageElement{}
	}

	normalizeLevelingAccess(&m.CommandsGlobal)

	if m.Commands == nil {
		m.Commands = map[string]LevelingCommand{}
	} else {
		for k, v := range m.Commands {
			normalizeLevelingAccess(&v.Access)
			m.Commands[k] = v
		}
	}
}

// normalizeLevelingAccess rellena las tres listas de IDs de un bloque de
// acceso por comando para que cada una serialice como `[]`.
func normalizeLevelingAccess(a *LevelingCommandAccess) {
	a.Roles.IDs = ensureStrSlice(a.Roles.IDs)
	a.Channels.IDs = ensureStrSlice(a.Channels.IDs)
	a.Categories.IDs = ensureStrSlice(a.Categories.IDs)
}

