package mocks

import (
	"time"

	"kena.bot/api-db-go/internal/domain/dbguild"
)

// levelingStr es un constructor local de *string para los defaults nullable
// del módulo de niveles (colores, contenido de texto del lienzo por
// defecto…). Privado al fichero para no colisionar con los constructores
// homólogos de otros mocks del paquete (`tempvoiceStr`, `ticketsStr`, …).
func levelingStr(s string) *string { return &s }

// levelingFloat es el gemelo de `levelingStr` para los floats nullable del
// lienzo por defecto (tamaño de letra, radio, valor de muestra de la
// barra…).
func levelingFloat(f float64) *float64 { return &f }

// levelingInt es el gemelo de `levelingStr` para los enteros nullable
// (grosor de letra).
func levelingInt(i int) *int { return &i }

// levelingCommandAccessDefault: sin restricción en los tres ejes. El módulo
// de niveles no tiene el caso especial de tempvoice (canal ceñido al recién
// creado): `rank` es un comando de lectura sin canal propio, así que el
// default global es simplemente "todos". Slices nuevos en cada llamada para
// que dos documentos no compartan el mismo array.
func levelingCommandAccessDefault() dbguild.LevelingCommandAccess {
	return dbguild.LevelingCommandAccess{
		Roles:      dbguild.LevelingAccessList{Mode: dbguild.LevelingAccessAllExcept, IDs: []string{}},
		Channels:   dbguild.LevelingAccessList{Mode: dbguild.LevelingAccessAllExcept, IDs: []string{}},
		Categories: dbguild.LevelingAccessList{Mode: dbguild.LevelingAccessAllExcept, IDs: []string{}},
	}
}

