	CommandMode        *dbguild.LevelingCommandMode          `json:"command_mode,omitempty"`
}

// maxLevelingRequirementBypassRoles: Discord no deja más de 250 roles por
// servidor (mismo tope que `maxJoinRoles` en greeter), así que una lista más
// larga sólo puede ser basura.
const maxLevelingRequirementBypassRoles = 250

// validateLevelingRequirements aplica los topes que el merge no puede: el
// repositorio escribe lo que le llega, así que un `min_membership_seconds`
// negativo o un `bypass_role_ids` con basura se guardarían tal cual y el bot
// los leería sin que nadie los hubiera comprobado. `r` nil (bloque `text`/
// `voice` ausente del body) es «no tocar» y no se valida.
func validateLevelingRequirements(r *dbguild.LevelingRequirements, prefix string) *apierrors.CustomError {
	if r == nil {
		return nil
	}

	for _, f := range []struct {
		value    int
		property string
	}{
		{r.MinMembershipSeconds, prefix + "min_membership_seconds"},
		{r.MinAccountAgeSeconds, prefix + "min_account_age_seconds"},
		{r.MinMessageLength, prefix + "min_message_length"},
	} {
		if f.value < 0 {
			return zodItemError("Too small: expected number to be >=0", f.property)
		}
	}

	if len(r.BypassRoleIDs) > maxLevelingRequirementBypassRoles {
		return zodItemError(
			"Too big: expected array to have <="+strconv.Itoa(maxLevelingRequirementBypassRoles)+" items",
			prefix+"bypass_role_ids",
		)
	}
	for _, id := range r.BypassRoleIDs {
		if !snowflakeRe.MatchString(id) {
			return zodItemError("Must be a Discord snowflake (17–20 digits)", prefix+"bypass_role_ids")
		}
	}

	return nil
}

// ValidateUpdateModuleLeveling aplica los topes de los bloques `requirements`
// de `text`/`voice` que el bind sólo comprueba en FORMA (el resto del cuerpo
// de niveles no tiene topes propios más allá del enum/struct — ver
// `UpdateModuleLevelingBody`). Sin esto un `min_membership_seconds: -1` o un
// `bypass_role_ids` no-snowflake se persistían tal cual y el bot los leería
// sin que ninguna capa los hubiera comprobado.
