// de `text`/`voice` que el bind sólo comprueba en FORMA (el resto del cuerpo
// de niveles no tiene topes propios más allá del enum/struct — ver
// `UpdateModuleLevelingBody`). Sin esto un `min_membership_seconds: -1` o un
// `bypass_role_ids` no-snowflake se persistían tal cual y el bot los leería
// sin que ninguna capa los hubiera comprobado.
func ValidateUpdateModuleLeveling(body *UpdateModuleLevelingBody) *apierrors.CustomError {
	if body == nil {
