	out["curve_multiplier"] = SerializeValue(m.CurveMultiplier)
	putJSONInline(out, "voice_rules", m.VoiceRules)
	putJSONInline(out, "excluded_channel_ids", m.ExcludedChannelIDs)
	putJSONInline(out, "excluded_role_ids", m.ExcludedRoleIDs)
	putJSONInline(out, "role_multipliers", m.RoleMultipliers)
	putJSONInline(out, "channel_multipliers", m.ChannelMultipliers)
	putJSONInline(out, "announce", m.Announce)
	putJSONInline(out, "rewards", m.Rewards)
	putJSONInline(out, "rank_card", m.RankCard)
	putJSONInline(out, "commands_global", m.CommandsGlobal)
	putJSONInline(out, "commands", m.Commands)
	out["command_mode"] = string(m.CommandMode)
	out["updated_at"] = dateField(m.UpdatedAt.Time)
	return out, nil
}

// nullableStringField encodes a `*string` the way the Node cache writer's
// `serializeValue` does: nil → "" (empty field), else the raw string as-is.
// On read, DeserializeValue("") → nil, round-tripping back to a nil pointer.
func nullableStringField(p *string) string {
	if p == nil {
		return ""
	}
	return *p
}

// nullableIntField — el gemelo de `nullableStringField` para `*int`: nil → ""
// (DeserializeValue("") = nil → puntero nil al decodificar el hash), número →
// su forma serializada normal.
func nullableIntField(p *int) string {
	if p == nil {
		return ""
	}
	return SerializeValue(*p)
}

// nullableDateField encodes el `enabled_since` opcional con la misma
// convención que el resto de nulos del hash: `__DATE__:<ISO>` cuando hay
// fecha, cadena vacía cuando no — `DeserializeValue("")` devuelve nil, que
// decodifica al puntero nil del struct. Evita repetir el if/else en los ocho
// marshallers.
func nullableDateField(d *dbguild.JSONDate) string {
	if d == nil {
		return ""
	}
	return dateField(d.Time)
}

