// LevelingRequirements mirrors `DBLevelingRequirements` — requisitos de
// elegibilidad para ganar XP con una fuente, pensados para el abuso, no para
// la burocracia: el caso que los motiva es la cuenta recién creada que entra,
// farmea nivel a base de mensajes de una letra y se va. Todo entero es
// segundos/caracteres con `0` = sin requisito; los cuatro `Ignore*` son
// SOLO TEXTO y se persisten igual en el bloque de voz por simetría de forma
// (mismo criterio que `LevelingVoiceRules` en el bloque de texto).
type LevelingRequirements struct {
	// MinMembershipSeconds: segundos que el miembro debe llevar EN EL
	// SERVIDOR antes de ganar XP. Sale de `joined_at`, que ya está en la
	// caché de miembros: ninguna petición extra a Discord.
	MinMembershipSeconds int `bson:"min_membership_seconds" json:"min_membership_seconds"`
	// MinAccountAgeSeconds: antigüedad mínima de la CUENTA de Discord. Se
	// deduce del snowflake del propio id de usuario, tampoco cuesta ninguna
	// petición.
	MinAccountAgeSeconds int `bson:"min_account_age_seconds" json:"min_account_age_seconds"`
	// MinMessageLength: SOLO TEXTO. Caracteres mínimos del mensaje, ya
	// recortado.
	MinMessageLength int `bson:"min_message_length" json:"min_message_length"`
	// IgnoreLinkOnly: SOLO TEXTO. Descarta el mensaje cuyo contenido,
	// quitado el enlace, queda vacío.
	IgnoreLinkOnly bool `bson:"ignore_link_only" json:"ignore_link_only"`
	// IgnoreAttachmentOnly: SOLO TEXTO. Descarta el mensaje sin texto que
	// solo trae adjuntos.
	IgnoreAttachmentOnly bool `bson:"ignore_attachment_only" json:"ignore_attachment_only"`
	// IgnoreStickerOrEmojiOnly: SOLO TEXTO. Descarta el mensaje que solo son
	// emojis (unicode o custom) o un sticker.
	IgnoreStickerOrEmojiOnly bool `bson:"ignore_sticker_or_emoji_only" json:"ignore_sticker_or_emoji_only"`
	// IgnoreCommands: SOLO TEXTO. Descarta el mensaje que empieza por el
	// prefijo del servidor.
	IgnoreCommands bool `bson:"ignore_commands" json:"ignore_commands"`
	// BypassRoleIDs: roles que se saltan TODOS los requisitos anteriores
	// (staff, boosters…).
	BypassRoleIDs []string `bson:"bypass_role_ids" json:"bypass_role_ids"`
}

// LevelingXpSource mirrors `DBLevelingXpSource` — una fuente de XP (texto o
// voz). `IntervalSeconds` significa cosas distintas en cada una y por eso NO
// se llama `Cooldown`: en texto es la ventana antispam (sólo el primer
// mensaje de la ventana da XP); en voz es la duración del tick (cada tick
// completo en voz concede una tirada).
type LevelingXpSource struct {
	Enabled         bool                  `bson:"enabled"          json:"enabled"`
	Min             int                   `bson:"min"              json:"min"`
	Max             int                   `bson:"max"              json:"max"`
	IntervalSeconds int                   `bson:"interval_seconds" json:"interval_seconds"`
	Requirements    LevelingRequirements  `bson:"requirements"     json:"requirements"`
}

// LevelingMultiplier mirrors `DBLevelingMultiplier` — multiplicador de XP
// atado a un rol o a un canal, según la lista en la que viva.
type LevelingMultiplier struct {
	ID         string  `bson:"id"         json:"id"`
	Multiplier float64 `bson:"multiplier" json:"multiplier"`
}

// LevelingReward mirrors `DBLevelingReward` — al alcanzar `Level` se
// conceden estos roles.
type LevelingReward struct {
	Level   int      `bson:"level"    json:"level"`
	RoleIDs []string `bson:"role_ids" json:"role_ids"`
}

// LevelingVoiceRules mirrors el objeto inline `ModuleLeveling.voice_rules`
// de la interfaz TS — cuándo NO cuenta el tiempo en voz.
type LevelingVoiceRules struct {
	IgnoreAlone    bool `bson:"ignore_alone"    json:"ignore_alone"`
	IgnoreMuted    bool `bson:"ignore_muted"    json:"ignore_muted"`
	IgnoreDeafened bool `bson:"ignore_deafened" json:"ignore_deafened"`
}

// LevelingAnnounce mirrors el objeto inline `ModuleLeveling.announce` de la
// interfaz TS. `Content` es un CENTINELA (ver `NewModuleLeveling` en el
// paquete `mocks`): mientras el guild lo tenga byte a byte igual al default
// de fábrica, bot y dashboard lo traducen con la clave i18n
// `announceDefault` — igual que `DEFAULT_TEMPVOICE_PANEL`.
type LevelingAnnounce struct {
	Enabled            bool                   `bson:"enabled"              json:"enabled"`
	Target             LevelingAnnounceTarget `bson:"target"               json:"target"`
	ChannelID          *string                `bson:"channel_id"           json:"channel_id"`
	Content            string                 `bson:"content"              json:"content"`
	DeleteAfterSeconds *int                   `bson:"delete_after_seconds" json:"delete_after_seconds"`
}

// LevelingRewards mirrors el objeto inline `ModuleLeveling.rewards` de la
// interfaz TS.
type LevelingRewards struct {
	Enabled  bool                    `bson:"enabled"  json:"enabled"`
	Stacking LevelingRewardStacking  `bson:"stacking" json:"stacking"`
	Levels   []LevelingReward        `bson:"levels"   json:"levels"`
}

// LevelingRankCard mirrors el objeto inline `ModuleLeveling.rank_card` de la
// interfaz TS. `Canvas` reutiliza `GreeterImageCanvas` tal cual — mismo
// lienzo que greeter, incluida la capa `bar` (ver el comentario de
// `GreeterImageElement.BarToken`).
type LevelingRankCard struct {
	Mode          LevelingCardMode   `bson:"mode"           json:"mode"`
	BackgroundURL *string            `bson:"background_url" json:"background_url"`
	AccentColor   string             `bson:"accent_color"   json:"accent_color"`
	Canvas        GreeterImageCanvas `bson:"canvas"         json:"canvas"`
}

// LevelingAccessList mirrors `DBAccessList` — la lista de acceso de un eje
// (roles/canales/categorías) del comando `rank`.
type LevelingAccessList struct {
	Mode LevelingAccessMode `bson:"mode" json:"mode"`
	IDs  []string           `bson:"ids"  json:"ids"`
}

// LevelingCommandAccess mirrors `DBCommandAccess` — acceso por eje (quién:
// roles, dónde: canales/categorías) del comando `rank`.
type LevelingCommandAccess struct {
	Roles      LevelingAccessList `bson:"roles"      json:"roles"`
	Channels   LevelingAccessList `bson:"channels"   json:"channels"`
	Categories LevelingAccessList `bson:"categories" json:"categories"`
}

// LevelingCommandSync mirrors el objeto inline `DBLevelingCommand.use_global`
// de la interfaz TS — herencia POR EJE del acceso global. Un eje en `true`
// lee de `commands_global`; en `false`, del `access` propio del comando.
// A diferencia de tempvoice/music, aquí no hace falta `UnmarshalJSON` para
// el booleano legacy: el módulo nace ya con la forma por eje, no existe
// ningún documento anterior que migrar.
type LevelingCommandSync struct {
	Roles      bool `bson:"roles"      json:"roles"`
	Channels   bool `bson:"channels"   json:"channels"`
	Categories bool `bson:"categories" json:"categories"`
}

// LevelingCommand mirrors `DBLevelingCommand` — gemelo de
// `DBTempVoiceCommand`/`TempvoiceCommand`, config del único comando
// configurable del módulo (`rank`).
type LevelingCommand struct {
	Enabled   bool                   `bson:"enabled"    json:"enabled"`

