// interfaz TS. `Canvas` reutiliza `GreeterImageCanvas` tal cual — mismo
// lienzo que greeter, incluida la capa `bar` (ver el comentario de
// `GreeterImageElement.BarToken`).
type LevelingRankCard struct {
