// ModuleLeveling matches `DBModuleLeveling`. Field order sigue la interfaz TS
// (no hay zod schema de Node del que copiar el orden — igual que tickets).
type ModuleLeveling struct {
	SchemaVersion int  `bson:"schema_version" json:"schema_version"`
	Enabled       bool `bson:"enabled"        json:"enabled"`
	// EnabledSince es la fecha de la PRIMERA activación del módulo en este
	// guild — WRITE-ONCE: se estampa al activar por primera vez y no se
	// reescribe nunca (ni al desactivar ni al reactivar). `nil` (campo
	// ausente en Mongo) = nunca activado. Mismo contrato que
	// `ModuleTempvoice.EnabledSince` / `ModuleTickets.EnabledSince`.
	EnabledSince       *JSONDate                  `bson:"enabled_since,omitempty" json:"enabled_since"`
	XPMode             LevelingXPMode             `bson:"xp_mode"              json:"xp_mode"`
	Text               LevelingXpSource           `bson:"text"                 json:"text"`
	Voice              LevelingXpSource           `bson:"voice"                json:"voice"`
	CurveMultiplier    float64                    `bson:"curve_multiplier"     json:"curve_multiplier"`
	VoiceRules         LevelingVoiceRules         `bson:"voice_rules"          json:"voice_rules"`
	ExcludedChannelIDs []string                   `bson:"excluded_channel_ids" json:"excluded_channel_ids"`
	ExcludedRoleIDs    []string                   `bson:"excluded_role_ids"    json:"excluded_role_ids"`
	RoleMultipliers    []LevelingMultiplier       `bson:"role_multipliers"     json:"role_multipliers"`
	ChannelMultipliers []LevelingMultiplier       `bson:"channel_multipliers"  json:"channel_multipliers"`
	Announce           LevelingAnnounce           `bson:"announce"             json:"announce"`
	Rewards            LevelingRewards            `bson:"rewards"              json:"rewards"`
	RankCard           LevelingRankCard           `bson:"rank_card"            json:"rank_card"`
	CommandsGlobal     LevelingCommandAccess      `bson:"commands_global"      json:"commands_global"`
	Commands           map[string]LevelingCommand `bson:"commands"             json:"commands"`
	CommandMode        LevelingCommandMode        `bson:"command_mode"         json:"command_mode"`
	UpdatedAt          JSONDate                   `bson:"updated_at"           json:"updated_at"`
}

// NormalizeLeveling rellena todo campo de colección que haya decodificado
// `nil` (de un documento parcial de Mongo o una entrada de caché vieja) con
// un valor vacío no-nil, para que el cuerpo JSON emita `[]`/`{}` en vez de
// `null`. Los escalares y los punteros nullable NO se tocan: un `null`
// almacenado sigue siendo `null`. Idempotente.
func NormalizeLeveling(m *ModuleLeveling) {
	if m == nil {
		return
	}

	m.ExcludedChannelIDs = ensureStrSlice(m.ExcludedChannelIDs)
	m.ExcludedRoleIDs = ensureStrSlice(m.ExcludedRoleIDs)
	m.RoleMultipliers = ensureLevelingMultiplierSlice(m.RoleMultipliers)
	m.ChannelMultipliers = ensureLevelingMultiplierSlice(m.ChannelMultipliers)

	m.Text.Requirements.BypassRoleIDs = ensureStrSlice(m.Text.Requirements.BypassRoleIDs)
	m.Voice.Requirements.BypassRoleIDs = ensureStrSlice(m.Voice.Requirements.BypassRoleIDs)

	m.Rewards.Levels = ensureLevelingRewardSlice(m.Rewards.Levels)
	for i := range m.Rewards.Levels {
		m.Rewards.Levels[i].RoleIDs = ensureStrSlice(m.Rewards.Levels[i].RoleIDs)
	}

	if m.RankCard.Canvas.Elements == nil {
		m.RankCard.Canvas.Elements = []GreeterImageElement{}
	}

	normalizeLevelingAccess(&m.CommandsGlobal)

	if m.Commands == nil {
		m.Commands = map[string]LevelingCommand{}
	} else {
		for k, v := range m.Commands {
			normalizeLevelingAccess(&v.Access)
			m.Commands[k] = v
		}
	}
}

// normalizeLevelingAccess rellena las tres listas de IDs de un bloque de
// acceso por comando para que cada una serialice como `[]`.
func normalizeLevelingAccess(a *LevelingCommandAccess) {
	a.Roles.IDs = ensureStrSlice(a.Roles.IDs)
	a.Channels.IDs = ensureStrSlice(a.Channels.IDs)
	a.Categories.IDs = ensureStrSlice(a.Categories.IDs)
}

func ensureLevelingMultiplierSlice(s []LevelingMultiplier) []LevelingMultiplier {
	if s == nil {
		return []LevelingMultiplier{}
	}
	return s
}

func ensureLevelingRewardSlice(s []LevelingReward) []LevelingReward {
	if s == nil {
		return []LevelingReward{}
	}
	return s
}

