package dbguild

import (
	"reflect"
	"testing"
)

// NormalizeTTS es la única corrección automática del subdocumento, y su valor
// está tanto en lo que arregla como en lo que NO toca: si algún día alguien
// «completa» la función sembrando `require_voice`/`say_name`, el fallo no se ve
// aquí — se ve como un ajuste que la dashboard guarda, api-db confirma y la
// siguiente lectura vuelve a encender.

func TestNormalizeTTS_BackfillsZeroValues(t *testing.T) {
	m := &ModuleTTS{}
	NormalizeTTS(m)

	if m.Language != DefaultTTSLanguage {
		t.Fatalf("Language = %q, want %q", m.Language, DefaultTTSLanguage)
	}
	if m.Speed != DefaultTTSSpeed {
		t.Fatalf("Speed = %v, want %v", m.Speed, DefaultTTSSpeed)
	}
	if m.MaxChars != DefaultTTSMaxChars {
		t.Fatalf("MaxChars = %d, want %d", m.MaxChars, DefaultTTSMaxChars)
	}
}

func TestNormalizeTTS_KeepsExplicitFalsesAndZeros(t *testing.T) {
	m := &ModuleTTS{
		RequireVoice:  false,
		SayName:       false,
		SkipEmoji:     false,
		RepeatedChars: 0,
		Language:      "en",
		Speed:         2,
		MaxChars:      50,
	}
	NormalizeTTS(m)

	if m.RequireVoice {
		t.Fatal("RequireVoice = true: normalizar el default `true` hace imposible desactivarlo")
	}
	if m.SayName {
		t.Fatal("SayName = true: normalizar el default `true` hace imposible desactivarlo")
	}
	if m.RepeatedChars != 0 {
		t.Fatalf("RepeatedChars = %d, want 0 (0 significa «recorte desactivado», no «sin valor»)", m.RepeatedChars)
	}
	if m.Language != "en" || m.Speed != 2 || m.MaxChars != 50 {
		t.Fatalf("valores explícitos pisados: %q / %v / %d", m.Language, m.Speed, m.MaxChars)
	}
}

func TestNormalizeTTS_IsIdempotent(t *testing.T) {
	m := &ModuleTTS{}
	NormalizeTTS(m)
	first := *m
	NormalizeTTS(m)

	// DeepEqual y no `!=`: desde v2 el struct lleva el mapa `commands`, que no
	// es comparable.
	if !reflect.DeepEqual(*m, first) {
		t.Fatalf("segunda pasada cambió el documento: %+v != %+v", *m, first)
	}
}

// El acceso por comando (v2) sí se siembra en Normalize, a diferencia de
// `require_voice`/`say_name`: aquí «ausente» y «false explícito» sí se
// distinguen, porque lo que se mira es la PRESENCIA de la clave en el mapa.

func TestNormalizeTTS_SeedsEveryConfigurableCommand(t *testing.T) {
	m := &ModuleTTS{}
	NormalizeTTS(m)

	if len(m.Commands) != len(TTSCommandNames) {
		t.Fatalf("commands tiene %d entradas, want %d", len(m.Commands), len(TTSCommandNames))
	}
	for _, name := range TTSCommandNames {
		cmd, ok := m.Commands[name]
		if !ok {
			t.Fatalf("falta el subcomando %q", name)
		}
		if !cmd.Enabled || !cmd.UseGlobal.Roles || !cmd.UseGlobal.Channels || !cmd.UseGlobal.Categories {
			t.Fatalf("commands[%q] = %+v, want activo y heredando los tres ejes", name, cmd)
		}
	}
	if m.CommandsGlobal.Roles.Mode != TTSAccessAllExcept || m.CommandsGlobal.Roles.IDs == nil {
		t.Fatalf("commands_global.roles = %+v, want all_except con lista no-nil", m.CommandsGlobal.Roles)
	}
}

// Regresión del fallo que se comió music en su día: sembrar por mapa entero en
// vez de por clave pisaba la configuración guardada en CADA lectura en frío.
func TestNormalizeTTS_KeepsStoredCommandConfig(t *testing.T) {
	m := &ModuleTTS{
		Commands: map[string]TTSCommand{
			"skip": {
				Enabled:   false,
				UseGlobal: TTSCommandSync{Roles: false, Channels: true, Categories: true},
				Access: TTSCommandAccess{
					Roles: TTSAccessList{Mode: TTSAccessOnly, IDs: []string{"dj"}},
				},
			},
		},
	}
	NormalizeTTS(m)

	skip := m.Commands["skip"]
	if skip.Enabled {
		t.Fatal("commands[skip].enabled volvió a true: el backfill pisó la configuración guardada")
	}
	if skip.UseGlobal.Roles {
		t.Fatal("commands[skip].use_global.roles volvió a true: el backfill pisó la herencia guardada")
	}
	if skip.Access.Roles.Mode != TTSAccessOnly || len(skip.Access.Roles.IDs) != 1 {
		t.Fatalf("commands[skip].access.roles = %+v, want only [dj]", skip.Access.Roles)
	}
	// Los ejes que el documento no traía se completan, sin tocar el que sí.
	if skip.Access.Channels.Mode != TTSAccessAllExcept || skip.Access.Channels.IDs == nil {
		t.Fatalf("commands[skip].access.channels = %+v, want all_except con lista no-nil", skip.Access.Channels)
	}
	// Y los subcomandos que faltaban aparecen, para que uno nuevo nazca activo.
	if len(m.Commands) != len(TTSCommandNames) {
		t.Fatalf("commands tiene %d entradas, want %d (los ausentes deben sembrarse)", len(m.Commands), len(TTSCommandNames))
	}
}

func TestNormalizeTTS_NilIsNoop(t *testing.T) {
	NormalizeTTS(nil)
}

