package dbguild

import "testing"

// TestNormalizeLeveling_RequirementsBypassRoleIDsBecomeEmpty 🛡️ — un módulo
// decodificado de un documento parcial de Mongo/caché deja
// `text.requirements.bypass_role_ids` / `voice.requirements.bypass_role_ids`
// en `nil`; tras NormalizeLeveling deben serializar como `[]`, nunca `null`
// (mismo invariante que el resto de colecciones del módulo).
func TestNormalizeLeveling_RequirementsBypassRoleIDsBecomeEmpty(t *testing.T) {
	m := &ModuleLeveling{}
	NormalizeLeveling(m)

	if m.Text.Requirements.BypassRoleIDs == nil {
		t.Fatal("text.requirements.bypass_role_ids sigue nil tras normalizar")
	}
	if m.Voice.Requirements.BypassRoleIDs == nil {
		t.Fatal("voice.requirements.bypass_role_ids sigue nil tras normalizar")
	}
	if len(m.Text.Requirements.BypassRoleIDs) != 0 || len(m.Voice.Requirements.BypassRoleIDs) != 0 {
		t.Fatalf("bypass_role_ids no vacío tras normalizar un módulo vacío: text=%v voice=%v",
			m.Text.Requirements.BypassRoleIDs, m.Voice.Requirements.BypassRoleIDs)
	}
}

// TestNormalizeLeveling_KeepsStoredRequirements — normalizar no debe pisar
// los requisitos ya guardados, sólo rellenar la colección nil.
func TestNormalizeLeveling_KeepsStoredRequirements(t *testing.T) {
	m := &ModuleLeveling{
		Text: LevelingXpSource{
			Requirements: LevelingRequirements{
				MinMembershipSeconds: 3600,
				IgnoreCommands:       true,
				BypassRoleIDs:        []string{"123456789012345678"},
			},
		},
	}
	NormalizeLeveling(m)

	if m.Text.Requirements.MinMembershipSeconds != 3600 {
		t.Fatalf("min_membership_seconds = %d, want 3600", m.Text.Requirements.MinMembershipSeconds)
	}
	if !m.Text.Requirements.IgnoreCommands {
		t.Fatal("ignore_commands volvió a false: normalizar pisó el valor guardado")
	}
	if len(m.Text.Requirements.BypassRoleIDs) != 1 || m.Text.Requirements.BypassRoleIDs[0] != "123456789012345678" {
		t.Fatalf("bypass_role_ids = %v, want [123456789012345678]", m.Text.Requirements.BypassRoleIDs)
	}
}

func TestNormalizeLeveling_NilIsNoop(t *testing.T) {
	NormalizeLeveling(nil)
}

