func TestValidateUpdateModuleLeveling_ValidRequirementsPass(t *testing.T) {
	body := &UpdateModuleLevelingBody{
		Text: &dbguild.LevelingXpSource{
			Requirements: dbguild.LevelingRequirements{
				MinMembershipSeconds: 3600,
				MinAccountAgeSeconds: 86400,
				MinMessageLength:     5,
				BypassRoleIDs:        []string{"123456789012345678"},
			},
		},
		Voice: &dbguild.LevelingXpSource{
			Requirements: dbguild.LevelingRequirements{MinMembershipSeconds: 0},
		},
	}
	if err := ValidateUpdateModuleLeveling(body); err != nil {
		t.Fatalf("requisitos válidos: got error %+v, want nil", err)
	}
