func TestValidateUpdateModuleLeveling_NegativeSecondsRejected(t *testing.T) {
	cases := []struct {
		name string
		req  dbguild.LevelingRequirements
	}{
		{"min_membership_seconds", dbguild.LevelingRequirements{MinMembershipSeconds: -1}},
		{"min_account_age_seconds", dbguild.LevelingRequirements{MinAccountAgeSeconds: -1}},
		{"min_message_length", dbguild.LevelingRequirements{MinMessageLength: -1}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			body := &UpdateModuleLevelingBody{
				Text: &dbguild.LevelingXpSource{Requirements: tc.req},
			}
			err := ValidateUpdateModuleLeveling(body)
			if err == nil {
				t.Fatalf("%s negativo: got nil error, want a validation error", tc.name)
			}
			if !strings.Contains(err.Property, "text.requirements."+tc.name) {
				t.Fatalf("Property = %q, want to contain %q", err.Property, "text.requirements."+tc.name)
			}
		})
	}
}

