		},
	}
	err := ValidateUpdateModuleLeveling(body)
	if err == nil {
		t.Fatal("bypass_role_ids inválido: got nil error, want a validation error")
	}
	if !strings.Contains(err.Property, "voice.requirements.bypass_role_ids") {
		t.Fatalf("Property = %q, want to contain voice.requirements.bypass_role_ids", err.Property)
	}
}

func TestValidateUpdateModuleLeveling_TooManyBypassRoleIDsRejected(t *testing.T) {
	ids := make([]string, maxLevelingRequirementBypassRoles+1)
	for i := range ids {
		ids[i] = "123456789012345678"
	}
	body := &UpdateModuleLevelingBody{
		Text: &dbguild.LevelingXpSource{
			Requirements: dbguild.LevelingRequirements{BypassRoleIDs: ids},
		},
	}
	err := ValidateUpdateModuleLeveling(body)
	if err == nil {
		t.Fatal("bypass_role_ids por encima del tope: got nil error, want a validation error")
	}
}

