func (h *ModuleLevelingHandler) Patch(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleLeveling]()
	ctx := c.Context()

	var body validations.UpdateModuleLevelingBody
	dec := json.NewDecoder(bytes.NewReader(c.Body()))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&body); err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	// El decode sólo comprueba la FORMA (enums, structs anidados). Los topes
	// de los bloques `requirements` (segundos negativos, roles que no son
	// snowflakes) no existían en ninguna capa del servidor.
	if verr := validations.ValidateUpdateModuleLeveling(&body); verr != nil {
		r.AddError(verr)
		return reply(c, r)
	}

	patch, err := patchMap(c.Body())
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}
